static void free_input_double_list(ifcopenshell_double_list_t *value) {
    PyMem_Free(value->items);
    value->items = NULL;
    value->size = 0;
}

static int make_input_double_list(PyObject *obj, ifcopenshell_double_list_t *out) {
    PyObject *seq = PySequence_Fast(obj, "Expected a sequence");
    if (!seq) return 0;
    Py_ssize_t size = PySequence_Fast_GET_SIZE(seq);
    out->items = size ? (double *)PyMem_Calloc((size_t)size, sizeof(double)) : NULL;
    out->size = (size_t)size;
    if (size && !out->items) {
        Py_DECREF(seq);
        PyErr_NoMemory();
        return 0;
    }
    for (size_t i = 0; i < (size_t)size; ++i) {
        out->items[i] = PyFloat_AsDouble(PySequence_Fast_GET_ITEM(seq, (Py_ssize_t)i));
        if (PyErr_Occurred()) {
            free_input_double_list(out);
            Py_DECREF(seq);
            return 0;
        }
    }
    Py_DECREF(seq);
    return 1;
}

static void free_input_string_list(ifcopenshell_string_list_t *value) {
    if (value->items) {
        for (size_t j = 0; j < value->size; ++j) {
            if (value->items[j].owned) {
                PyMem_Free(value->items[j].data);
            }
        }
    }
    PyMem_Free(value->items);
    value->items = NULL;
    value->size = 0;
}

static int make_input_string_list(PyObject *obj, ifcopenshell_string_list_t *out) {
    PyObject *seq = PySequence_Fast(obj, "Expected a sequence");
    if (!seq) return 0;
    Py_ssize_t size = PySequence_Fast_GET_SIZE(seq);
    out->items = size ? (ifcopenshell_string_t *)PyMem_Calloc((size_t)size, sizeof(ifcopenshell_string_t)) : NULL;
    out->size = (size_t)size;
    if (size && !out->items) {
        Py_DECREF(seq);
        PyErr_NoMemory();
        return 0;
    }
    for (size_t i = 0; i < (size_t)size; ++i) {
        Py_ssize_t size = 0;
        const char *data = PyUnicode_AsUTF8AndSize(PySequence_Fast_GET_ITEM(seq, (Py_ssize_t)i), &size);
        if (!data) {
            free_input_string_list(out);
            Py_DECREF(seq);
            return 0;
        }
        out->items[i].data = (char *)PyMem_Malloc((size_t)size + 1);
        if (!out->items[i].data) {
            free_input_string_list(out);
            Py_DECREF(seq);
            PyErr_NoMemory();
            return 0;
        }
        memcpy(out->items[i].data, data, (size_t)size + 1);
        out->items[i].size = (size_t)size;
        out->items[i].owned = true;
    }
    Py_DECREF(seq);
    return 1;
}

